import LLMCore
import SwiftUI

/// Open-source packages linked into the app, with their license texts
/// (`Acknowledgements.json`, generated by `scripts/gen-acknowledgements.py`).
struct AcknowledgementsView: View {
    private let packages = Acknowledgements.load()

    var body: some View {
        List {
            Section {
                ForEach(packages) { package in
                    NavigationLink {
                        LicenseTextView(package: package)
                    } label: {
                        HStack(alignment: .firstTextBaseline) {
                            VStack(alignment: .leading, spacing: 3) {
                                Text(verbatim: package.name)
                                    .font(.subheadline.weight(.medium))
                                    .foregroundStyle(Theme.textPrimary)
                                Text(verbatim: package.version)
                                    .font(.mono(.caption))
                                    .foregroundStyle(Theme.textTertiary)
                            }
                            Spacer(minLength: 8)
                            Text(verbatim: package.license)
                                .font(.mono(.caption, weight: .medium))
                                .foregroundStyle(Theme.textSecondary)
                        }
                    }
                    .listRowBackground(Theme.groupedRow)
                }
            } footer: {
                SectionFooter("Pocket LLM is built on these open-source projects. Thank you to their authors.")
            }
        }
        .scrollContentBackground(.hidden)
        .background(Theme.groupedBackground)
        .navigationTitle(Text("Acknowledgements"))
        .navigationBarTitleDisplayMode(.inline)
    }
}

private struct LicenseTextView: View {
    let package: Acknowledgements.Package
    @Environment(\.openURL) private var openURL

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                if let url = URL(string: package.url) {
                    Button {
                        openURL(url)
                    } label: {
                        HStack(spacing: 4) {
                            Text(verbatim: url.host().map { "\($0)\(url.path())" } ?? package.url)
                                .lineLimit(1)
                                .truncationMode(.middle)
                            Image(systemName: "arrow.up.right").font(.caption2.weight(.bold))
                        }
                        .font(.mono(.footnote))
                        .foregroundStyle(Theme.textSecondary)
                        .frame(minHeight: 44)
                    }
                    .buttonStyle(.plain)
                }
                ForEach(package.texts, id: \.file) { text in
                    VStack(alignment: .leading, spacing: 8) {
                        Text(verbatim: text.file)
                            .font(.mono(.caption, weight: .semibold))
                            .foregroundStyle(Theme.textTertiary)
                        Text(verbatim: text.text)
                            .font(.mono(.caption2))
                            .foregroundStyle(Theme.textSecondary)
                            .textSelection(.enabled)
                    }
                }
            }
            .padding(Theme.margin)
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .background(Theme.groupedBackground)
        .navigationTitle(Text(verbatim: package.name))
        .navigationBarTitleDisplayMode(.inline)
    }
}

/// The license of every catalog model, with links to the license text and the model files.
struct ModelLicensesView: View {
    let catalog: [ModelSpec]

    var body: some View {
        List {
            Section {
                ForEach(catalog) { spec in
                    VStack(alignment: .leading, spacing: 6) {
                        HStack(alignment: .firstTextBaseline) {
                            Text(verbatim: spec.displayName)
                                .font(.subheadline.weight(.medium))
                                .foregroundStyle(Theme.textPrimary)
                            Spacer(minLength: 8)
                            LicenseBadge(license: spec.license)
                                .padding(.vertical, -9)
                        }
                        if let page = AppLinks.huggingFacePage(for: spec) {
                            Link(destination: page) {
                                Text(verbatim: "huggingface.co/\(spec.repoID)")
                                    .font(.mono(.caption))
                                    .foregroundStyle(Theme.textTertiary)
                                    .lineLimit(1)
                                    .truncationMode(.middle)
                            }
                            .accessibilityHint(Text("Opens the model page in Safari"))
                        }
                    }
                    .padding(.vertical, 4)
                    .listRowBackground(Theme.groupedRow)
                }
            } footer: {
                SectionFooter("Model weights are published by their authors under these licenses and are downloaded only when you ask.")
            }
        }
        .scrollContentBackground(.hidden)
        .background(Theme.groupedBackground)
        .navigationTitle(Text("Model licenses"))
        .navigationBarTitleDisplayMode(.inline)
    }
}

enum Acknowledgements {
    struct Package: Decodable, Identifiable {
        struct LicenseText: Decodable {
            let file: String
            let text: String
        }

        let name: String
        let version: String
        let url: String
        let license: String
        let texts: [LicenseText]
        var id: String { name }
    }

    private struct File: Decodable {
        let packages: [Package]
    }

    static func load() -> [Package] {
        guard let url = Bundle.main.url(forResource: "Acknowledgements", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let file = try? JSONDecoder().decode(File.self, from: data)
        else { return [] }
        return file.packages
    }
}
